      if(action==='logout'){journal();await request('/logout',{});ready=false;login=true;error='';paint();return;}if(action==='retry'){error='';boot();return;}if(action==='refresh'){await task('正在同步最新考试与成绩…',async()=>apply(await request('/state')));return;}
