      if(action==='preview'){preview=!preview;paint();return;}if(action==='full'){full=!full;paint();return;}
      if(action==='preview-modal'){modal(previewQuestion(draft(),true));enhance();return;}if(action==='paper-preview'){const p=s().papers.find(p=>p.id===(d.id||paperId));modal(`<h2>${esc(p.name)} · 学生视角</h2><p>${p.items.length} 道题 · ${totalPoints(p)} 分 · ${p.minutes} 分钟</p>${p.items.map(i=>previewQuestion(i.question)).join('')}`);enhance();return;}
