      if(action==='batch'){if(!checks.size)throw new Error('请先选择题目');modal(`<h2>批量编辑 ${checks.size} 道题目</h2><form id="xp-batch" class="ec-form ec-modal-form"><label>分类（留空保持原值）<input name="category" maxlength="60"></label><label>追加标签<input name="tags" maxlength="300" placeholder="逗号分隔"></label><label>审核状态<select name="status"><option value="">保持原值</option><option value="pending">退回待审核</option><option value="approved">已检查答案与来源，审核通过</option></select></label><label class="ec-check"><input name="confirmed" type="checkbox" required>我已逐题核对选中题目的答案、解析和来源</label><button class="ec-primary">保存批量修改</button></form>`);return;}
