      if(['bold','italic','formula'].includes(action)){const area=document.querySelector('[name="stem"]'),wrappers={bold:['**','**'],italic:['*','*'],formula:['$','$']},[a,b]=wrappers[action];area.setRangeText(a+(area.value.slice(area.selectionStart,area.selectionEnd)||(action==='formula'?'E=mc^2':'文字'))+b,area.selectionStart,area.selectionEnd,'select');area.dispatchEvent(new Event('input',{bubbles:true}));return;}
