        if(action==='take-document'){const doc=ctx.documents().find(doc=>doc.id===d.id);const source=makeSource(doc.name,doc.segments.map(x=>x.text).join('\n'));source.docMorphId=doc.id;source.segments=clone(doc.segments);s().sources.unshift(source);aiConfig.sourceId=source.id;await save('从 DocMorph 导入来源');closeModal();}
        if(action==='close-exam')apply(await request('/close',{id:d.id}));
